(function () {
  const root = document.querySelector('#add');
  if (!root) return;

  const viewport = root.querySelector('[data-add-viewport]');
  const track = root.querySelector('[data-add-track]');
  const slides = Array.from(root.querySelectorAll('.add__slide'));
  const btnPrev = root.querySelector('.add__btn[data-dir="prev"]');
  const btnNext = root.querySelector('.add__btn[data-dir="next"]');

  if (!viewport || !track || slides.length < 2 || !btnPrev || !btnNext) return;

  // чтобы не резало и расчеты были адекватными
  slides.forEach(s => { s.style.boxSizing = 'border-box'; s.style.minWidth = '0'; });
  track.style.minWidth = '0';

  let index = 0;
  let currentX = 0;

  const getGap = () => {
    const cs = getComputedStyle(track);
    const gap = parseFloat(cs.gap || cs.columnGap || cs.rowGap || '0');
    return Number.isFinite(gap) ? gap : 0;
  };

  const getStep = () => {
    const first = slides[0];
    if (!first) return 0;
    return first.getBoundingClientRect().width + getGap();
  };

  const getVisibleCount = () =>
    window.matchMedia('(max-width: 1024px)').matches ? 1 : 2;

  const setBtnState = (btn, disabled) => {
    btn.dataset.disabled = disabled ? '1' : '0';
    btn.style.opacity = disabled ? '0.4' : '1';
    btn.style.pointerEvents = disabled ? 'none' : 'auto';
    btn.setAttribute('aria-disabled', disabled ? 'true' : 'false');
    btn.tabIndex = disabled ? -1 : 0;
  };

  const clampIndex = () => {
    const visible = getVisibleCount();
    const maxIndex = Math.max(0, slides.length - visible);
    index = Math.min(Math.max(index, 0), maxIndex);
    return maxIndex;
  };

  const setTransition = (on) => {
    track.style.transition = on ? 'transform 250ms ease' : 'none';
  };

  const getMaxTranslate = () => {
    const maxIndex = Math.max(0, slides.length - getVisibleCount());
    const step = getStep();
    return -maxIndex * step;
  };

  const applyTranslate = (x) => {
    const min = getMaxTranslate(); // отрицательное
    const max = 0;

    // лёгкая "резинка" за края
    if (x > max) x = max + (x - max) * 0.25;
    if (x < min) x = min + (x - min) * 0.25;

    currentX = x;
    track.style.transform = `translate3d(${x}px, 0, 0)`;
  };

  const render = () => {
    const maxIndex = clampIndex();
    const step = getStep();
    currentX = -index * step;

    setTransition(true);
    track.style.transform = `translate3d(${currentX}px, 0, 0)`;

    setBtnState(btnPrev, index === 0);
    setBtnState(btnNext, index === maxIndex);
  };

  const move = (dir) => {
    const maxIndex = clampIndex();
    if (dir === 'next' && index >= maxIndex) return;
    if (dir === 'prev' && index <= 0) return;

    index += (dir === 'next' ? 1 : -1);
    render();
  };

  btnPrev.addEventListener('click', (e) => { e.preventDefault(); move('prev'); });
  btnNext.addEventListener('click', (e) => { e.preventDefault(); move('next'); });

  // --- SWIPE / DRAG ---
  track.style.willChange = 'transform';
  viewport.style.touchAction = 'pan-y'; // вертикальный скролл ок

  let dragging = false;
  let startX = 0;
  let startY = 0;
  let startTranslate = 0;
  let moved = 0;
  let lockedAxis = null; // 'x' | 'y' | null
  let isSwipe = false;   // ВАЖНО: был ли реальный горизонтальный свайп

  const onDown = (e) => {
    if (e.isPrimary === false) return;

    // если начали на ссылке/кнопке — не стартуем drag (ссылка приоритетнее)
    if (e.target && e.target.closest && e.target.closest('a, button')) {
      dragging = false;
      lockedAxis = null;
      moved = 0;
      isSwipe = false;
      return;
    }

    dragging = true;
    lockedAxis = null;
    moved = 0;
    isSwipe = false;

    startX = e.clientX;
    startY = e.clientY;
    startTranslate = currentX;

    setTransition(false);
    viewport.setPointerCapture?.(e.pointerId);
  };

  const onMove = (e) => {
    if (!dragging) return;

    const dx = e.clientX - startX;
    const dy = e.clientY - startY;

    if (!lockedAxis) {
      if (Math.abs(dx) < 6 && Math.abs(dy) < 6) return;
      lockedAxis = Math.abs(dx) > Math.abs(dy) ? 'x' : 'y';
    }

    if (lockedAxis === 'y') {
      // даём странице скроллиться
      dragging = false;
      setTransition(true);
      return;
    }

    // горизонтальный свайп — блокируем нативный скролл
    e.preventDefault();

    moved = dx;
    if (Math.abs(dx) > 10) isSwipe = true; // ВАЖНО: фиксируем факт свайпа

    applyTranslate(startTranslate + dx);
  };

  const onUp = () => {
    if (!dragging) return;
    dragging = false;

    const step = getStep();
    const threshold = Math.min(80, step * 0.25);

    if (Math.abs(moved) > threshold) {
      index += (moved < 0 ? 1 : -1);
    }

    render();

    // ВАЖНО: сброс moved, чтобы клики после свайпа не были заблокированы навсегда
    moved = 0;
    // isSwipe сбросится на следующем onDown
  };

  viewport.addEventListener('pointerdown', onDown, { passive: true });
  viewport.addEventListener('pointermove', onMove, { passive: false });
  viewport.addEventListener('pointerup', onUp, { passive: true });
  viewport.addEventListener('pointercancel', onUp, { passive: true });
  viewport.addEventListener('lostpointercapture', onUp, { passive: true });

  // блокируем клик ТОЛЬКО если реально был горизонтальный свайп
  viewport.addEventListener('click', (e) => {
    if (isSwipe) {
      e.preventDefault();
      e.stopPropagation();
    }
  }, true);

  // ресайз
  let raf = 0;
  window.addEventListener('resize', () => {
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => {
      setTransition(false);
      clampIndex();
      render();
    });
  });

  render();
})();

