{
  --d:#e2533b; --i:#f5a623; --s:#39b54a; --c:#2f7bf6;
  --line:#e4e8f1; --radius:16px; --shadow:0 8px 30px rgba(25,45,80,.10);
}
*{box-sizing:border-box}
*{box-sizing:border-box}
trait-item{display:flex;align-items:center;gap:12px;padding:16px;border-radius:14px;background:#fff;border:1px solid var(--line);box-shadow:0 4px 14px rgba(25,45,80,.05)}
trait-swatch{width:40px;height:40px;border-radius:50%;flex:0 0 auto;display:grid;place-items:center;color:#fff;font-weight:800}
trait-item h4{margin:0;font-size:18px}
trait-item p{margin:2px 0 0;font-size:14px;color:var(--muted)}
.footnote{margin-top:16px;color:var(--muted);font-size:14px}
footer{background:#0d1c33;color:#aeb9cf;padding:40px 0;font-size:14px}
footer a{color:#9fb6ff}
.checklist{list-style:none;padding:0;margin:14px 0 0;display:flex;flex-direction:column;gap:8px;max-width:640px}
.checklist li{padding-left:26px;position:relative;color:rgba(255,255,255,.85)}
.checklist li::before{content:"";position:absolute;left:0;top:3px;width:16px;height:16px;border-radius:50%;background:rgba(255,255,255,.18)}
/* ---------- Modal ---------- */
.modal{position:fixed;inset:0;z-index:100;display:none}
.modal.is-open{display:block}
.modal__overlay{position:absolute;inset:0;background:rgba(12,25,48,.55);backdrop-filter:blur(2px)}
.modal__dialog{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  width:min(860px,94vw);max-height:92vh;overflow:hidden;background:#fff;border-radius:20px;
  box-shadow:0 24px 70px rgba(9,23,50,.28);display:flex;flex-direction:column}
.modal__close{position:absolute;top:12px;right:14px;z-index:5;width:38px;height:38px;border-radius:50%;
  border:0;background:#eef1f7;color:#334;cursor:pointer;font-size:22px;line-height:1}
.modal__close:hover{background:#e2e8f3}
.modal__head{padding:22px 24px 12px;text-align:center}
.modal__title{font-size:26px;margin:0 0 8px}
.modal__sub{color:var(--muted);font-size:15px;margin:0 0 6px}
.modal__lead{color:var(--ink);font-size:15px;font-weight:600}
.tabs{display:flex;gap:6px;justify-content:center;padding:6px 16px;flex-wrap:wrap}
.tab{border:0;background:#f2f4f9;border-radius:999px;padding:8px 12px;cursor:pointer;font-size:13px;
  font-weight:600;color:var(--muted);padding:8px 12px}
.tab:hover{background:#e9edf6}
.tab.is-active{background:var(--brand);color:#fff}
.modal__data{position:relative;flex:1;overflow-y:auto;padding:8px 22px 20px}
@supports not (backdrop-filter:blur(2px)){.modal__overlay{background:rgba(12,25,48,.6)}}
.modal__body .progress{height:5px;background:#eef1f7;border-radius:4px;margin:-6px 0 14px;overflow:hidden}
.modal__body .progress__bar{height:100%;background:var(--brand);width:12.5%;transition:width .25s ease}
.pane{display:none}
.pane.is-active{display:block}
.pane__note{margin:0 0 14px;text-align:center;color:var(--muted);font-size:14px}
.list{border:1px solid var(--line);border-radius:16px;overflow:hidden;background:#fff;box-shadow:0 4px 14px rgba(25,45,80,.05)}
.list__row{display:flex;min-height:70px;gap:0}
.list__cell{flex:1;position:relative;border-right:1px solid var(--line)}
.list__cell:last-child{border-right:0}
.list__cell .cell-tag{position:absolute;top:7px;left:10px;font-size:11px;font-weight:700;letter-spacing:.04em;
  text-transform:uppercase;color:var(--muted);z-index:2;pointer-events:none}
.list__item{position:absolute;inset:10px 8px;border-radius:12px;border:1px solid var(--line);
  background:#f9fafc;display:flex;align-items:center;justify-content:center;text-align:center;
  font-size:15px;font-weight:600;cursor:pointer;user-select:none;padding:6px;transition:box-shadow .12s ease, border-color .12s ease}
.list__item:hover{background:#fff;box-shadow:0 4px 14px rgba(25,45,80,.12)}
.list__item.selected{background:var(--brand-soft);border-color:var(--brand);color:var(--brand-d)}
.list-cell__drag{position:absolute;top:50%;left:8px;transform:translateY(-50%);display:flex;flex-direction:column;gap:2px;opacity:.4}
.list-cell__drag span{width:12px;height:2px;background:#6b7890;border-radius:2px}
.list__item.dragging{opacity:.4}
.list__item.drop-before{box-shadow:0 0 0 2px var(--brand) inset}
.list__item.drop-after{box-shadow:0 0 0 2px var(--brand) inset}
@media (hover:hover) and (pointer:fine){
  .list__item{cursor:grab}
  .list__item.dragging{cursor:grabbing}
  .list__item{padding-left:34px}
}
@supports (pointer:coarse){}
.modal__actions{display:flex;gap:12px;justify-content:center;padding:14px 22px;border-top:1px solid var(--line)}
.modal__actions .btn{min-width:130px}
/* ---------- Results ---------- */
.result{padding:16px 22px 24px;overflow-y:auto;max-height:86vh}
.result__top{text-align:center;margin-bottom:8px}
.result__top .hit{font-size:14px;color:var(--muted);margin:0}
.result__h{text-align:center;margin:6px 0 14px}
.bar{margin:8px 0}
.bar__label{display:flex;justify-content:space-between;font-weight:700;font-size:15px;margin-bottom:4px}
.bar__label small{font-weight:600;color:var(--muted)}
.bar__track{height:12px;background:#eef1f7;border-radius:999px;overflow:hidden}
.bar__fill{height:100%;border-radius:999px;transition:width .5s ease}
.chart{display:flex;align-items:flex-end;gap:14px;justify-content:center;height:180px;margin:8px 0 12px}
.chart__col{display:flex;flex-direction:column;align-items:center;gap:6px;flex:1;max-width:120px}
.chart__col b{font-size:13px}
.chart__val{font-weight:800;font-size:15px}
.chart__bar{width:100%;background:transparent;border-top-left-radius:8px;border-top-right-radius:8px;transition:height .6s ease}
.bands{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:8px}
@media(max-width:820px){.bands{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.bands{grid-template-columns:1fr}}
.band{border:1px solid var(--line);border-radius:14px;padding:14px;background:#fff}
.band h4{margin:0 0 4px;font-size:16px}
.band p{margin:0;font-size:13px;color:var(--muted)}
</style>
</head>
<body>
<header class="site">
  <div class="wrap">
    <span class="kicker">Адресная методика DISC</span>
    <h1>Тест DISC: определите свой управленческий стиль</h1>
    <p class="hero-sub">Узнайте, каков ваш типичный стиль поведения и общения и как он сказывается на управлении.<br>Это не «приговор» и не «характер» — это лишь инструмент самооценки вашего <em>стиля поведения</em>. Точно так же, как и любой другой, это ваш <em>природный</em> или, если хотите так назвать, «домашний» стиль.</p>
    <button id="openBtn" class="btn btn-primary" type="button">Пройти тест →</button>
  </div>
</header>

<section class="pad">
  <div class="wrap" style="grid-gap:18px;display:grid;grid-template-columns:auto 1fr 1fr;gap:18px;margin-bottom:10px">
    <span class="kicker">Как это работает</span>
    <p class="lead">Тест DISC основан на модели, которая была разработана и применена больше, чем в течение 1950-х годов Уилломем Хенли, доктором философии.</p>
  </div>
  <div class="cards3" style="margin-top:10px">
    <div class="feature">
      <div class="ico"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg></div>
      <h3>24 блока утверждений</h3>
      <p>8 серий по 4 качества, которые нужно ранжировать от наиболее к наименее похожему на вас — с помощью перетаскивания.</p>
    </div>
    <div class="feature">
      <div class="ico"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M19 9l-5 5-4-4-4 4"/></svg></div>
      <h3>Управленческий стиль</h3>
      <p>Решения в сложных условиях: как вы ведете себя под давлением, в стрессе, в кризисе. Именно это и есть проявление вашего лидерства.</p>
    </div>
    <div class="feature">
      <div class="ico" data-ico=svg-container style="width:42px;height:42px;border-radius:11px;background:var(--brand-soft);display:grid;place-items:center;margin-bottom:12px"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2a10 10 0 1 0 10 10"/><path d="M12 6v6l4 2"/></svg></div>
      <h3>Управление временем</h3>
      <p>Как вы распоряжаете своим временем: на что вы тратите больше всего часов в неделю, а на что не успеваете.</p>
    </div>
  </div>
  <div class="traits">
    <div class="trait-item"><span class="trait-swatch" style="background:#e2533b">D</span><div><h4>Доминантный</h4><p>Решительность и напор.</p></div></div>
    <div class="trait-item"><span class="trait-swatch" style="background:#f5a623">I</span><div><h4>Экспресcивный</h4><p>Энергия и влияние.</p></div></div>
    <div class="trait-item"><span class="trait-swatch" style="background:#39b54a">S</span><div><h4>Установочный</h4><p>Надежность и спокойствие.</p></div></div>
    <div class="trait-item"><span class="trait-swatch" style="background:#2f7bf6">C</span><div><h4>Систематичный</h4><p>Анализ и точность.</p></div></div>
  </div>
  <p class="footnote">Этот тест не является психодиагностическим инструментом, не ставит диагнозов и не заменяет консультацию специалистов по управлению персоналом.<br><br>Тест DISC — это инструмент самооценки, который помогает лучше понять свой стиль общения и управления.</p>
</section>

<footer>
  <div class="wrap">
    <p>Инструмент самооценки по методике DISC. Работает локально в вашем браузере — ваши данные никуда не отправляются.</p>
  </div>
</footer>

<div class="modal" id="wizard" role="dialog" aria-modal="true" aria-labelledby="wtitle">
  <div class="modal__overlay" data-close></div>
  <div class="modal__dialog">
    <button class="modal__close" type="button" data-close aria-label="Закрыть">×</button>
    <div class="modal__head">
      <h2 class="modal__title" id="wtitle">Дисциплинарный тест DISC: определение управленческого стиля</h2>
      <p class="modal__sub">Запишите, пожалуйста, ваш результат в конце теста и перепроверьте его еще раз! Затем нажмите кнопку «Назад».</p>
      <p class="modal__lead">Если вы заметили, что какой-либо блок вы не успели, но хотите вернуться к нему позже — просто нажмите на соответствующую вкладку выше.</p>
    </div>
    <div class="tabs" role="tablist">
      <button class="tab is-active" data-step-nums="0" type="button">1 из 8</button>
      <button class="tab" data-step-nums="1" type="button">2 из 8</button>
      <button class="tab" data-step-nums="2" type="button">3 из 8</button>
      <button class="tab" data-step-nums="3" type="button">4 из 8</button>
      <button class="tab" data-step-nums="4" type="button">5 из 8</button>
      <button class="tab" data-step-nums="5" type="button">6 из 8</button>
      <button class="tab" data-step-nums="6" type="button">7 из 8</button>
      <button class="tab" data-step-nums="7" type="button">8 из 8</button>
    </div>
    <div class="modal__body">
      <div class="progress"><div class="progress__bar" id="progBar"></div></div>
      <div id="lists"></div>
    </div>
    <div class="modal__actions">
      <button class="btn btn-ghost" id="prevBtn" type="button">← Назад</button>
      <button class="btn btn-primary" id="nextBtn" type="button">Далее →</button>
    </div>
  </div>
</div>

<div class="modal" id="result" role="dialog" aria-modal="true" aria-labelledby="rtitle">
  <div class="modal__overlay" data-close></div>
  <div class="modal__dialog" style="width:min(760px,94vw)">
    <button class="modal__close" type="button" data-close aria-label = "Закрыть">×</button>
    <div class="result">
      <p class="result__top" style="margin:8px 0 2px">Ваш результат</p>
      <p class="result__hit" style="text-align:center;color:var(--muted);font-size:14px;margin:0 0 10px"></p>
      <div class="result__h" style="margin:0 0 16px"></div>
      <div class="chart" id="chart"></div>
      <div class="bands" id="bands"></div>
      <p style="text-align:center;margin:18px 0 8px">
        <button class="btn btn-primary" id="restartBtn" type="button">Пройти ещё раз</button>
      </p>
    </div>
  </div>
</div>

<script>
var DISC_QUESTIONS=(function(){
