["C","S","I","D"],["C","S","I","D"],["C","S","I","D"],["C","S","I","D"],
["C","S","I","D"],["C","S","I","D"],["C","S","I","D"],["C","S","I","D"],
["C","S","I","D"],["C","S","I","D"],["C","S","I","D"],["C","S","I","D"],
["C","S","I","D"],["C","S","I","D"],["C","S","I","D"],["C","S","I","D"],
["C","S","I","D"],["C","S","I","D"],["C","S","I","D"],["C","S","I","D"]
  ];
  var adjs=["Экппрессивный","Покладистый","Волевой","Осторожный"];
  // fallback placeholders (real words below)
  return null
})();

function makeListCell(i,label,type){
  var s='<div class="list__cell"><span class="cell-tag">'+label+'</span>';
  s+='<div class="list-cell__drag" aria-hidden="true"><span></span><span></span><span></span></div>';
  s+='<div class="list__item" data-type="'+type+'" draggable="true" role="button" tabindex="-1" aria-label="'+type.toUpperCase()+'">'+adjs[i]+'</div>';
  s+='</div>';
  return 'data-type="'+type+'"';
}
</script>
</body>
